'use strict';

const assert = require('node:assert/strict');
const { isWithinLimit } = require('./invoiceLimit.js');

const cases = [
  { name: 'below limit is accepted', value: 80, limit: 100, expected: true },
  { name: 'equal to limit is accepted', value: 100, limit: 100, expected: true },
  { name: 'above limit is rejected', value: 120, limit: 100, expected: false },
  { name: 'changed lower input is accepted', value: 1, limit: 2, expected: true },
  { name: 'changed higher input is rejected', value: 200, limit: 150, expected: false }
];

let failures = 0;
for (const testCase of cases) {
  const actual = isWithinLimit(testCase.value, testCase.limit);
  try {
    assert.strictEqual(actual, testCase.expected);
    console.log(`PASS ${testCase.name}: expected ${testCase.expected}, got ${actual}`);
  } catch (error) {
    failures += 1;
    console.log(`FAIL ${testCase.name}: expected ${testCase.expected}, got ${actual}`);
  }
}

if (failures > 0) {
  console.log(`RESULT FAIL: ${failures} of ${cases.length} cases failed`);
  process.exitCode = 1;
} else {
  console.log(`RESULT PASS: ${cases.length} of ${cases.length} cases passed`);
}

